import{_ as t,o as s,c as n,af as a}from"./chunks/framework.Dt3O48XQ.js";const g=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md","lastUpdated":null}'),o={name:"en/guide/installation.md"};function i(r,e,d,l,c,p){return s(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Node.js <strong>&gt;= 20.9.0</strong></li><li>MySQL / MariaDB</li><li><strong>Redis</strong> — required for matchmaking / chat queues; optional if you only exercise HTTP. Enable Redis before using <code>MatchmakingDemo</code>.</li></ul><h2 id="install-dependencies" tabindex="-1">Install dependencies <a class="header-anchor" href="#install-dependencies" aria-label="Permalink to &quot;Install dependencies&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>Create <strong><code>.env.development</code></strong> (local) or <strong><code>.env.production</code></strong> in the <strong>server repo root</strong>. Load order is described in the Chinese <a href="/xcs.github.io/guide/configuration.html">Configuration</a> page (first sections).</p><p>Minimal example below; replace <code>your_*</code> placeholders with your MySQL credentials and a strong secret.</p><table tabindex="0"><thead><tr><th>Variable</th><th>What it is</th></tr></thead><tbody><tr><td><strong><code>NODE_ENV</code></strong></td><td>Node environment. <strong><code>development</code></strong> selects <strong><code>.env.development</code></strong> and dev-oriented behaviour in <code>src/config</code>.</td></tr><tr><td><strong><code>PORT</code></strong></td><td>Single port for <strong>HTTP + Colyseus WebSocket</strong> (default <strong>2567</strong> → <code>http://localhost:2567</code>, Swagger <code>/api-docs</code>, etc.).</td></tr><tr><td><strong><code>DB_HOST</code></strong></td><td><strong>MySQL / MariaDB</strong> host (<code>localhost</code> on your machine).</td></tr><tr><td><strong><code>DB_PORT</code></strong></td><td>Database port (<strong>3306</strong> for MySQL by default).</td></tr><tr><td><strong><code>DB_USERNAME</code></strong> / <strong><code>DB_PASSWORD</code></strong></td><td>DB login; never commit real passwords.</td></tr><tr><td><strong><code>DB_DATABASE</code></strong></td><td>Database <strong>schema name</strong> (create the empty DB first). Entities/migrations: see project-structure docs (Chinese).</td></tr><tr><td><strong><code>JWT_SECRET</code></strong></td><td>Symmetric secret used to <strong>sign access tokens</strong> (same tokens required by <strong><code>@RequireAuth()</code></strong> room options). Use a long random string in production.</td></tr><tr><td><strong><code>JWT_EXPIRES_IN</code></strong></td><td>Access-token lifetime string (<code>1h</code>, <code>24h</code>, …) passed to <code>jsonwebtoken</code> <code>expiresIn</code>. Refresh tokens / <code>JWT_REFRESH_*</code>: see <strong>“Redis 与 JWT”</strong> in <a href="/xcs.github.io/guide/configuration.html">Configuration</a>.</td></tr></tbody></table><p>Redis, <code>DB_TYPE</code>, <code>DB_SYNCHRONIZE</code>, and the rest are listed in <a href="/xcs.github.io/guide/configuration.html">Configuration</a>.</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NODE_ENV=development</span></span>
<span class="line"><span>PORT=2567</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DB_HOST=localhost</span></span>
<span class="line"><span>DB_PORT=3306</span></span>
<span class="line"><span>DB_USERNAME=root</span></span>
<span class="line"><span>DB_PASSWORD=your_password</span></span>
<span class="line"><span>DB_DATABASE=your_database</span></span>
<span class="line"><span></span></span>
<span class="line"><span>JWT_SECRET=your_jwt_secret_key</span></span>
<span class="line"><span>JWT_EXPIRES_IN=1h</span></span></code></pre></div><h2 id="run-dev-server" tabindex="-1">Run dev server <a class="header-anchor" href="#run-dev-server" aria-label="Permalink to &quot;Run dev server&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Visit <code>http://localhost:2567/api-docs</code> and the static home page. For Colyseus rooms, follow <a href="/xcs.github.io/en/guide/getting-started.html">Quick start</a> step 3–4.</p><div class="info custom-block"><p class="custom-block-title">Translation status</p><p>The longest environment tables live in the <strong>Chinese</strong> configuration page: <strong><a href="/xcs.github.io/guide/configuration.html">配置说明 →</a></strong>.</p></div>`,16)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
